+    Promise.all([a, b]).then(([left, right]) => {
+      if (left.isErr) return Result.err<[T, U], E | F>(left.error);
+      if (right.isErr) return Result.err<[T, U], E | F>(right.error);
+      return Result.ok<[T, U], E | F>([left.value, right.value]);
