+describe('collection combinators', () => {
+  test('Maybe iterates Just values and short-circuits iterable helpers', () => {
+    expect([...maybe.just(1)]).toEqual([1]);
+    expect([...maybe.nothing<number>()]).toEqual([]);
+
+    let advanced = 0;
+    function* values() {
+      yield maybe.just(1);
+      yield maybe.nothing<number>();
+      advanced += 1;
+      yield maybe.just(3);
+    }
+
+    expect(maybe.sequence(values()).isNothing).toBe(true);
